class Scheduler:
    def __init__(self, dependencies):
        self.parents = {task: set(items) for task, items in dependencies.items()}
        nodes = set(self.parents)
        for items in self.parents.values():
            nodes.update(items)
        for task in nodes:
            self.parents.setdefault(task, set())

        self.children = {task: set() for task in nodes}
        for task, parents in self.parents.items():
            for parent in parents:
                self.children[parent].add(task)

        self.remaining = {task: len(parents) for task, parents in self.parents.items()}
        self.state = {task: 'PENDING' for task in nodes}

    def start(self):
        for task, count in self.remaining.items():
            if count == 0:
                self._submit(task)

    def _submit(self, task):
        self.state[task] = 'RUNNING'
        print(f'Submit {task}')

    def on_success(self, task):
        self.state[task] = 'SUCCEEDED'
        for child in self.children[task]:
            self.remaining[child] -= 1
            if self.remaining[child] == 0 and self.state[child] == 'PENDING':
                self._submit(child)

class CompletionGate:
    def __init__(self, parents, submit):
        self.parents = {task: set(items) for task, items in parents.items()}
        nodes = set(self.parents)
        for items in self.parents.values():
            nodes.update(items)
        for task in nodes:
            self.parents.setdefault(task, set())

        self.children = {task: set() for task in nodes}
        for task, prerequisites in self.parents.items():
            for parent in prerequisites:
                self.children[parent].add(task)

        self.state = {task: 'PENDING' for task in nodes}
        self.submit = submit

    def on_finished(self, task, succeeded):
        self.state[task] = 'SUCCEEDED' if succeeded else 'FAILED'
        for child in self.children[task]:
            self._resolve(child)

    def _resolve(self, task):
        if self.state[task] != 'PENDING':
            return
        parent_states = [self.state[parent] for parent in self.parents[task]]
        if any(state in ('FAILED', 'SKIPPED') for state in parent_states):
            self.state[task] = 'SKIPPED'
            for child in self.children[task]:
                self._resolve(child)
        elif all(state == 'SUCCEEDED' for state in parent_states):
            self.state[task] = 'RUNNING'
            self.submit(task)

import heapq


def prioritized_order(prerequisites, priority):
    nodes = set(prerequisites)
    for parents in prerequisites.values():
        nodes.update(parents)

    children = {task: set() for task in nodes}
    indegree = {task: 0 for task in nodes}
    for task in nodes:
        parents = prerequisites.get(task, set())
        indegree[task] = len(parents)
        for parent in parents:
            children[parent].add(task)

    ready = []
    for task, count in indegree.items():
        if count == 0:
            heapq.heappush(ready, (priority.get(task, 0), task))

    order = []
    while ready:
        _, task = heapq.heappop(ready)
        order.append(task)
        for child in children[task]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, (priority.get(child, 0), child))

    if len(order) != len(nodes):
        raise ValueError('Dependency cycle detected')
    return order
